"""Layer 15 MLP down-projection component 907: a weak, diffuse signal.

What it does: its activation is slightly positive on average (about 0.07) with
a large spread (std about 0.31) and no single trigger. Read as a rough tendency
(not a rule), it is:
  - a little higher on special/markup tokens and on line breaks and punctuation,
    and lower on plain words and Chinese characters;
  - higher when the current token already appeared earlier in the same document;
  - essentially zero at the first token of a document.

The program adds these tendencies up. They explain only about 1% of the
component's variance on held-out text, so it is a description of a small bias,
not a detector.
"""

import re

READS = ()

VALUE = {"special": 0.20, "newline": 0.12, "punct": 0.10, "space": 0.085, "word": 0.045, "cjk": 0.03}
REPEAT_BONUS = 0.04


def token_class(s):
    if re.fullmatch(r"<\|.*\|>|</?[a-z_]+>", s):
        return "special"
    if s.strip() == "":
        return "newline" if "\n" in s else "space"
    if re.fullmatch(r"\s?[^\w\s]+", s):
        return "punct"
    if re.fullmatch(r"\s?[一-鿿]+", s):
        return "cjk"
    return "word"


def step(carry, prefix, upstream):
    seen, last_doc = carry if carry is not None else (set(), None)
    doc = prefix.document_ids[-1]
    if doc != last_doc:
        seen = set()  # a new document starts: nothing has been seen yet
        first = True
    else:
        first = False
    tok = prefix.token_ids[-1]
    if first:
        value = 0.0
    else:
        value = VALUE[token_class(prefix.token_strings[-1])]
        if tok in seen:
            value += REPEAT_BONUS
    seen.add(tok)
    return (seen, doc), value

"""Layer 15, MLP neuron 913 (the component reads almost only this hidden unit).

Its activation is near 0.03 on most tokens and goes strongly negative in text about
doing better and not repeating mistakes: "this time", "next time", "do better",
"the same mistakes", "make sure", "never again", "prevent", "avoid", "ensure".
It leans mildly positive on words about keeping or protecting something ("save",
"maintain", "protect"). Most of its variation comes from the many small, unexplained
fluctuations, which words do not capture, so this program explains only a little.
"""

READS = ()

MEAN = 0.03  # the component's typical activation

# Words of correction, prevention and resolve to do better next time.
CORRECTION = {
    "again", "avoid", "prevent", "never", "ensure", "future", "better", "improve",
    "improving", "improvement", "fix", "learned", "lesson", "repeat", "previous",
}
# Words about keeping, saving or protecting something.
PRESERVE = {"save", "maintain", "protect", "keep", "preserve", "comfort", "defense", "stay"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    prev = ""
    if len(prefix.token_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]:
        prev = prefix.token_strings[-2].strip().lower()
    if word == "time" and prev in ("this", "next", "last"):
        return carry, MEAN - 4.0
    if word == "better" and prev == "do":
        return carry, MEAN - 10.0
    if word in ("mistake", "mistakes") and prev in ("same", "my", "previous", "past"):
        return carry, MEAN - 12.0
    if word == "sure" and prev == "make":
        return carry, MEAN - 1.0
    if word in CORRECTION:
        return carry, MEAN - 0.5
    if word in PRESERVE:
        return carry, MEAN + 0.3
    return carry, MEAN

"""Layer-15 MLP neuron 914 (the component is essentially this hidden unit).

Its activation is small and noisy almost everywhere. The clearest pattern is lexical:
it runs negative on words of conflict, opposition, threat and anger ("refused",
"threat", "enemy", "conflict", "opposed", "hostile"), and a little past them, and
positive on words of courts and judicial outcomes ("Court", "jury", "judge",
"Appeals", "denied", "arrested"). Everywhere else it predicts 0.
"""

READS = ()

CONFLICT = {
    "refuse", "refused", "refusing", "threat", "threats", "threaten", "threatened",
    "enemy", "enemies", "conflict", "opposition", "oppose", "opposed", "hostile",
    "hostility", "hate", "angry", "anger", "outraged", "resist", "protest", "protested",
    "dispute", "disagree", "disagrees", "disagreed", "controversy", "tension", "fight",
    "fighting", "clash", "challenge", "uncomfortable", "jealous", "afraid", "offended",
}
COURT = {
    "court", "courts", "judge", "jury", "appeals", "appeal", "circuit", "conviction",
    "convicted", "arrested", "police", "denied", "trial", "verdict", "lawsuit",
}
SPILL = 2  # tokens after a conflict word that also lean negative


def word(token):
    return token.strip().lower().strip(".,;:!?\"'“”’()")


def step(carry, prefix, upstream):
    left = carry or 0
    if len(prefix.document_ids) > 1 and prefix.document_ids[-1] != prefix.document_ids[-2]:
        left = 0
    w = word(prefix.token_strings[-1])
    if w in CONFLICT:
        return SPILL, -1.0
    if w in COURT:
        return 0, 0.8
    if left > 0:
        return left - 1, -0.4
    return 0, 0.0

"""Layer 15 MLP hidden unit 916 (down_proj component 916), read as a comparison detector.

What it is: component 916 is mostly the MLP hidden unit 916 of layer 15 (its activation
correlates about 0.85 with that unit's contribution), read out through its down-projection.
Read straight through the unembedding, its output direction favours words like "usual",
"standard", "typical", "normally" and "expected".

When it fires: mostly on words that open or close a comparison or a reference to a
familiar state, such as "as expected", "as described", "as shown", "previously", "the same
as", "than we", "what he". It is weakly positive on subject pronouns and auxiliaries too.
This rule explains only about 1% of its variance: most of it comes from context that no
word list captures, and a token-lookup table explains only about 1-4%.

This program predicts a small positive value on those words and 0 elsewhere.
"""

READS = ()

# words that introduce a comparison or a relative clause
MARKERS = {"as", "than", "like", "what", "which", "wie", "comme", "que", "como"}
# words that refer back to a known or usual state
REFERENCE = {
    "previously", "described", "expected", "shown", "mentioned", "discussed", "specified",
    "listed", "stated", "usual", "usually", "normal", "normally", "typical", "standard",
    "conventional", "traditional", "original", "originally", "earlier", "intended", "supposed",
    "needed", "outlined", "noted", "indicated",
}
# subject pronouns and auxiliaries, weakly positive inside clauses
CLAUSE_WORDS = {"you", "i", "it", "we", "they", "he", "she", "one", "would", "had", "been", "can", "could"}


def word(text):
    return text.strip().lower()


def step(carry, prefix, upstream):
    n = len(prefix.token_strings)
    doc = prefix.document_ids[-1]
    # the last five tokens of this document, oldest first
    last = [
        word(prefix.token_strings[i]) if prefix.document_ids[i] == doc else ""
        for i in range(max(0, n - 5), n)
    ]
    cur = last[-1]
    prev = last[-2] if len(last) > 1 else ""
    value = 0.0
    if cur in CLAUSE_WORDS:
        value = 0.15
    if prev in MARKERS:
        value = max(value, 1.0)
    if cur in REFERENCE:
        value = max(value, 1.5)
    if prev == "as" and "same" in last[:-2]:
        value = 2.5
    return carry, float(value)

"""Layer 15 MLP down_proj, component 917: a code-syntax detector.

What it does: it goes negative on the words and symbols of source code, and most
strongly on control-flow keywords that open a statement (if / for / while / switch at
the start of an indented line). Declaration keywords (class, func, main, void, ...) and
header glue (in, ->, (, comparisons) are negative in proportion to how code-like the
recent text is. Ordinary prose stays near zero. The optional-type marker '?:' is
positive. The predictions use only the current token, its line position and the
code-density of the last 32 tokens of its document.

This is a heuristic summary of the activations, not the model's own computation. It
captures the negative, code-header side of the component; it does not explain the
rarer, large positive values on C++/TypeScript type declarations.
"""

import re

CONTROL = {"if", "for", "while", "switch", "foreach", "elif"}
DECLARE = {"class", "extends", "implements", "throws", "namespace", "main", "func",
           "function", "def", "public", "void", "int", "static", "struct", "fn", "impl"}
GLUE = {"(", "in", "->", "==", "!=", "&&", "||"}
OTHER_PUNCT = {")", ";", ":", "<", ">", "::", "!", "&", "*", "="}
CODE_CHARS = re.compile(r"[{};()\[\]=<>]|->|::")
WINDOW = 32

READS = ()


def _code_density(prefix):
    """Fraction of the last WINDOW tokens of this document that carry code characters."""
    t = prefix.position
    doc = prefix.document_ids[t]
    seen = code = 0
    for i in range(t - 1, max(-1, t - 1 - WINDOW), -1):
        if prefix.document_ids[i] != doc:
            break
        seen += 1
        code += bool(CODE_CHARS.search(prefix.token_strings[i]))
    return code / seen if seen else 0.0


def _starts_line(prefix):
    """True if only indentation separates this token from the start of its line."""
    i = prefix.position - 1
    while i >= 0 and prefix.token_strings[i].strip() == "":
        if "\n" in prefix.token_strings[i]:
            return True
        i -= 1
    return i < 0 or "\n" in prefix.token_strings[i]


def step(carry, prefix, upstream):
    word = prefix.token_strings[prefix.position].strip()
    density = _code_density(prefix)
    if word in CONTROL:
        value = -10.0 if _starts_line(prefix) else -12.0 * density
    elif word in DECLARE:
        value = -6.0 * density
    elif word in GLUE:
        value = -4.0 * density
    elif word in OTHER_PUNCT:
        value = -1.5 * density
    elif word == "?:":
        value = 4.0
    else:
        value = 0.0
    return carry, value

"""Pre-verb detector for layers.15.mlp.down_proj:935 (Qwen3-1.7B, layer 15 MLP).

The component goes strongly negative at a position where the text is about to
need a bare verb (or a verb-like continuation) next. Its activation is almost
zero elsewhere. The clearest cases:

  * modal verbs: "can", "could", "will", "must", "should", "may" (about -11)
  * negation after an auxiliary or modal: "can't", "don't", "not", "never" (about -7)
  * subject pronouns that open a clause: "if they", "and I", ". We" (about -7.5);
    the same pronouns after a verb or preposition, as objects, sit near zero
  * infinitive "to": "need to", "want to", "going to", "able to" (about -10.5),
    whereas a prepositional "to" ("to the store", "due to") stays near -4
  * auxiliaries "is", "was", "have", "been", "do" (about -4)
  * relative "that" / "which" (about -3.5) and pre-verb adverbs "also", "just" (about -3)

Everything else (nouns, articles, punctuation, lowercase "i", the month "May")
is predicted as 0. The program looks only at the current word and the word
before it, which is all it needs to tell these cases apart. It treats the
start of a document as a clause opener.
"""

from collections.abc import Mapping

READS: tuple[str, ...] = ()

# Words that are followed by a bare verb.
MODALS = {"can", "could", "may", "might", "must", "shall", "should", "will", "would", "cannot", "ought", "'ll"}

# Words that take a to-infinitive ("need to", "want to"), so a following "to" is an infinitive.
INFINITIVE_WORDS = {
    "need", "needs", "needed", "want", "wants", "wanted", "going", "have", "has", "had", "able",
    "unable", "ready", "try", "tried", "trying", "how", "way", "time", "used", "is", "was", "like",
    "likely", "supposed", "allowed", "decided", "expected", "possible",
}

SUBJECT_PRONOUNS = {"I", "you", "he", "she", "it", "we", "they", "who", "You", "He", "She", "It", "We", "They"}
OBJECT_PRONOUNS = {"me", "us", "them", "him", "her"}
NEGATIONS = {"not", "never", "ever", "'t", "Never"}
AUXILIARIES = {"is", "are", "was", "were", "be", "been", "being", "has", "have", "had", "do", "does", "did", "'ve"}
RELATIVES = {"that", "which"}
ADVERBS = {"also", "just", "only", "still", "always", "often", "already", "rather", "even"}

# Words that open a clause, so a pronoun after one of them is a subject.
CLAUSE_OPENERS = {"and", "but", "or", "so", "if", "when", "that", "as", "because", "while", "what", "where",
                  "which", "who", "how", "since", "until", "though", "although", "than", "unless", "then"}

# Mean activation for each class, fitted on sampled tokens.
VALUE = {
    "modal": -11.0,
    "to_infinitive": -10.5,
    "to_preposition": -4.0,
    "subject_after_opener": -7.5,
    "subject_elsewhere": -5.0,
    "object_pronoun": -1.5,
    "negation": -7.5,
    "auxiliary": -4.0,
    "relative": -3.5,
    "adverb": -3.0,
    "other": 0.0,
}


def _norm(token: str) -> str:
    return token.strip().replace("’", "'")


def _category(word: str, prev: str) -> str:
    if word == "to":
        return "to_infinitive" if prev.lower() in INFINITIVE_WORDS else "to_preposition"
    if word in MODALS:
        return "modal"
    if word in SUBJECT_PRONOUNS:
        opens = prev == "" or not prev[0].isalnum() or prev.lower() in CLAUSE_OPENERS
        return "subject_after_opener" if opens else "subject_elsewhere"
    if word in OBJECT_PRONOUNS:
        return "object_pronoun"
    if word in NEGATIONS:
        return "negation"
    if word in AUXILIARIES:
        return "auxiliary"
    if word in RELATIVES:
        return "relative"
    if word in ADVERBS:
        return "adverb"
    return "other"


def step(carry, prefix, upstream: Mapping):
    tokens = prefix.token_strings
    word = _norm(tokens[-1])
    same_document = len(prefix.document_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = _norm(tokens[-2]) if same_document else ""
    return carry, VALUE[_category(word, prev)]

"""Java source code detector (negative inside Java files).

This component reads the MLP's hidden state and writes into the residual stream.
Its activation is strongly negative on the words of Java source code and close to
zero elsewhere (prose, Python, JavaScript, LaTeX). The strongest values fall on the
header keywords that begin import and package lines, then on access modifiers
(public, private, ...), then on Java type and keyword words.

How strongly a position counts as Java, J between 0 and 1:
- J = 1 once the document has shown a Java declaration line (a package or import
  line ending in ';', or a class or interface declaration);
- before that, J ramps up with a decaying count of recent Java words (decay 0.95,
  saturating at 6), so unmarked Java such as method signatures also gets a value.

The predicted activation is J times a weight for the current token's kind:
import/package -22, access modifiers -13, Java type and keyword words -8,
other tokens -3. Non-Java text predicts 0.
"""
import re

READS = ()

HEADER = {"import", "package"}
MODIFIERS = {"public", "private", "protected", "static", "final"}
JAVA_WORDS = {
    "void", "String", "class", "return", "new", "java", "org", "com", "util",
    "List", "Map", "Override", "boolean", "int", "this", "null", "try", "catch",
    "extends", "implements", "interface", "throws", "@",
}
JAVA_LINE = re.compile(
    r"^\s*(package\s+[\w.]+\s*;|import\s+(static\s+)?[\w.*]+\s*;"
    r"|(public|private|protected)\s+(\w+\s+)*(class|interface|enum)\s)"
)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry["doc"] != doc:
        carry = {"doc": doc, "java": False, "ema": 0.0, "line": ""}
    text = prefix.token_strings[-1]
    word = text.strip()

    # how Java-like the position is, from the text before it
    j = 1.0 if carry["java"] else min(1.0, carry["ema"] / 6.0)
    if word in HEADER:
        weight = -22.0
    elif word in MODIFIERS:
        weight = -13.0
    elif word in JAVA_WORDS:
        weight = -8.0
    else:
        weight = -3.0
    value = j * weight

    # update the state with the newest token
    carry["ema"] = 0.95 * carry["ema"] + (1.0 if word in JAVA_WORDS else 0.0)
    carry["line"] += text
    if "\n" in carry["line"]:
        *done, rest = carry["line"].split("\n")
        if any(JAVA_LINE.match(line) for line in done):
            carry["java"] = True
        carry["line"] = rest
    return carry, float(value)

"""Layer-15 MLP hidden unit 948 (the component's only strong input direction).

It is a quantity-context detector with mixed sign. Shortly after a number:
  - a word naming a duration or length (words, minutes, hours, days...) pushes it up;
  - a word naming a counted thing (people, votes, languages, goals...) pushes it down;
  - a preposition (of, for, on, from...) right after a quantity pushes it down a little.
Digits and punctuation carry a weak upward push; everything else predicts 0.
"""

READS = ()

TIME_UNITS = {"word", "words", "minute", "minutes", "min", "hour", "hours", "day", "days",
              "week", "weeks", "month", "months", "year", "years", "second", "seconds", "time", "times"}
COUNTED = {"people", "votes", "viewers", "languages", "goals", "hits", "runs", "samples",
           "critics", "columns", "players", "students", "patients", "cases", "men", "women"}
PREPS = {"of", "for", "on", "from", "to", "in", "by", "with", "per"}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1].strip().lower()
    doc = prefix.document_ids[-1]
    last_doc, last_digit = carry if carry is not None else (None, -99)
    t = prefix.position
    if doc != last_doc:
        last_digit = -99
    has_digit = any(ch.isdigit() for ch in tok)
    gap = t - last_digit
    value = 0.0
    if has_digit:
        value = 0.08
        last_digit = t
    elif 1 <= gap <= 2:
        if tok in TIME_UNITS:
            value = 0.47
        elif tok in COUNTED:
            value = -2.5
        elif not tok.isalnum() and tok:
            value = 0.14
    if 1 <= gap <= 3 and tok in PREPS:
        value = -0.36
    return (doc, last_digit), value

"""Negative activation where a text is building a list of points.

Component 953 of layer 15's MLP down projection reads mostly MLP hidden unit 953 (about
44% of its direction's squared norm), so its activation follows that unit: mostly small,
with large negative swings at enumeration and list boundaries. The program predicts
those swings from the current token and the few tokens before it:

- an additive or enumerating connective ("also", "First", "Moreover", "Furthermore", ...)
  is itself negative;
- the comma or period that follows such a connective is more negative;
- bullets and dashes that start list items are negative;
- a semicolon, a line-ending period, and other commas and periods are weakly negative.

Everything else is predicted as 0. These values are rough group means, so the program
captures only a small part of the activation's variance: most of it is diffuse and
depends on context this program does not read.
"""

READS = ()

ADDITIVE = {
    "also", "moreover", "furthermore", "additionally", "further", "first", "firstly",
    "second", "secondly", "third", "thirdly", "finally", "lastly", "addition",
    "alternatively", "similarly",
}
PUNCT = {",", ".", ":", ")"}
DASHES = {"-", "•", "*", "●"}


def _word(token):
    return token.strip().lower()


def step(carry, prefix, upstream):
    tokens = prefix.token_strings
    current = tokens[-1]
    word = _word(current)
    recent = [_word(t) for t in tokens[-4:-1]]
    if word in ADDITIVE:
        return carry, -0.65
    if word in PUNCT and any(w in ADDITIVE for w in recent):
        return carry, -0.95
    if word in DASHES:
        return carry, -0.25
    if word == ";":
        return carry, -0.4
    if word == "." and "\n" in current:
        return carry, -0.4
    if word in PUNCT:
        return carry, -0.12
    return carry, 0.0

"""Comparison detector for layers.15.mlp.down_proj, component 955.

What it responds to, in plain terms: the component is switched on when the text is
stating, or is about to state, a comparison between two quantities or things. It is
strongest on
  - the second half of a comparative: "less [than]", "greater [than]", "smaller [than]"
    (about 5 on average; "rather than" is not a comparison and gets nothing);
  - "to" after a closeness or equality word: "close [to]", "equal [to]", "similar [to]",
    "parallel [to]" (about 4);
  - "up [to]" as a bound (about 3);
  - comparison operators written as symbols: ==, !=, >=, <=, >, <, and their
    variants (about 2.4);
  - comparison and equality words themselves: equal, match, similar, close, less,
    more, greater, exceed, below, above, consistent, ... (about 1.3);
  - a plain equals sign "=" (about 0.6) and other "than" (about 2).
Everything else, including most ordinary text, is set to 0.

The values are the average activation of each class over 16k training rows. The
program explains the large positive peaks only. Most of the component's variance is
diffuse, small, and spread across ordinary tokens (its activation is also often
negative there), and this program does not model it.
"""

from collections.abc import Mapping

READS: tuple[str, ...] = ()

OPERATORS = {"==", "===", "!=", "!==", "≠", ">=", "≥", "<=", "≤", "<", ">"}

RELATION_WORDS = {
    "equal", "equals", "equivalent", "same", "identical", "close", "closer", "closest",
    "near", "nearer", "nearest", "similar", "comparable", "parallel", "proportional",
    "approximately", "match", "matches", "matching", "matched", "meet", "meets",
    "exceed", "exceeds", "exceeding", "exceeded", "beyond", "above", "below",
    "less", "more", "greater", "smaller", "larger", "bigger", "fewer", "higher",
    "lower", "least", "most", "align", "aligns", "aligned", "consistent", "related",
}

COMPARATIVES = {
    "less", "more", "greater", "smaller", "larger", "bigger", "fewer", "higher",
    "lower", "longer", "shorter", "later", "earlier", "slower", "faster", "better",
    "worse", "further", "farther", "closer",
}

CLOSENESS = {
    "equal", "close", "closer", "closest", "near", "nearer", "nearest", "similar",
    "parallel", "comparable", "identical", "opposite", "equivalent", "proportional",
}

VALUES = {
    "comparative_than": 5.2,
    "closeness_to": 3.9,
    "up_to": 2.8,
    "operator": 2.4,
    "relation_word": 1.3,
    "other_than": 2.0,
    "equals_sign": 0.6,
}


def _word(text: str) -> str:
    return text.strip().lower()


def step(carry, prefix, upstream: Mapping):
    cur = _word(prefix.token_strings[-1])
    prev = ""
    if len(prefix.token_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]:
        prev = _word(prefix.token_strings[-2])
    if cur == "than" and prev in COMPARATIVES:
        kind = "comparative_than"
    elif cur == "than" and prev == "rather":
        kind = None
    elif cur == "than":
        kind = "other_than"
    elif cur == "to" and prev in CLOSENESS:
        kind = "closeness_to"
    elif cur == "to" and prev == "up":
        kind = "up_to"
    elif cur in OPERATORS:
        kind = "operator"
    elif cur in RELATION_WORDS:
        kind = "relation_word"
    elif cur == "=":
        kind = "equals_sign"
    else:
        kind = None
    return carry, float(VALUES[kind]) if kind else 0.0
